const q=(u,n,prompt,options,answer,why,concept)=>({id:`geo.a.g3.${u}.${n}`,prompt,options,answer,why,concept:'geo.a.glacier.'+concept});
const make=(slug,title,refs,cards,tasks,practice,check,model,cardViews)=>({id:'geography.a.glaciers.'+slug,topicId:'geography.a.glaciers',option:'glaciers',title,refs,cards,tasks,practice,check,model,cardViews,minutes:25});
export const glacierLessons3=[
make('water-supply','Upland water storage and supply',['1.13b: water storage and supply','Integrated skill 16: diagram introduction'],[
 ['Why an upland valley?','High rainfall in many western uplands can supply water, and a steep-sided valley can offer a basin for storage behind a dam. Stored water can support homes and industry beyond the uplands. Supply still depends on catchment inputs, storage capacity, demand, water quality and infrastructure. A wet climate does not guarantee that a particular reservoir never faces shortage.'],
 ['Follow a water budget','Over a defined period, final storage = initial storage + inflow − supply outflow − other losses. Our invented store starts at1000m³, receives300m³ and loses200m³ to supply plus50m³ to other losses:1050m³ remains. With only50m³ inflow and the same withdrawals/losses,800m³ remains. These are teaching cases, not Thirlmere measurements. Real budgets can require further pathways and capacity/spill limits.'],
 ['A supply benefit changes a landscape','Dams and raised water levels can inundate habitats, farmland, buildings and earlier shorelines. Roads, aqueducts and woodland management add changes; water levels and releases can affect shores and downstream habitats. Thirlmere’s nineteenth-century enlargement connected a glaciated valley to Manchester’s water demand. Compare reliable supply with financial, social and ecological costs rather than calling every reservoir an unqualified benefit.']
],[['Predict: keep withdrawals and losses unchanged but reduce inflow. Storage at the end tends to…',['Be lower','Rise automatically','Become unrelated to water input'],0],['Calculate the invented wet case:1000+300−200−50. Final storage is…',['1050m³','1550m³','50m³'],0],['Which is a landscape cost of raising reservoir water levels?',['Inundating existing land and habitats','Removing all need for maintenance','Preventing every drought forever'],0],['Why investigate the catchment and demand together?',['Both supply inputs and withdrawals affect the budget','Demand cannot affect storage','Rainfall is identical everywhere'],0]],
[q('water','p1','An invented store has600m³, receives150m³ and loses100m³ to supply plus20m³ otherwise. Final storage?',['630m³','870m³','30m³'],0,'600+150−100−20=630m³. Account for each input and output once.','water-budget'),q('water','p2','Why is upland rainfall alone insufficient to judge a scheme?',['Demand, capacity, water quality and infrastructure also matter','Every valley has unlimited storage','All reservoirs supply only nearby houses'],0,'Evaluate the system, not only one physical advantage.','water-supply'),q('water','p3','Reservoir enlargement can change habitats because…',['Land is inundated and shore conditions change','All living things instantly benefit equally','Water levels never change'],0,'Benefits for supply can coexist with ecological and social costs.','reservoir-impact')],
[q('water','c1','An invented store starts700m³, receives100m³, supplies80m³ and loses20m³ otherwise. Final storage?',['700m³','900m³','100m³'],0,'700+100−80−20=700m³. This is a constructed teaching example.','water-budget'),q('water','c2','Which physical combination can favour upland reservoir development?',['Water input and a suitable valley basin','A guarantee of no rain ever','Identical flat land without any catchment'],0,'Rainfall, relief and basin suitability can help, alongside other constraints.','water-supply'),q('water','c3','Which is a possible disadvantage of a new reservoir?',['Flooding existing land uses and habitats','Infinite capacity at no cost','No downstream effects under any conditions'],0,'Storage infrastructure changes a landscape and creates trade-offs.','reservoir-impact'),q('water','c4','A defensible water-supply judgement should…',['Compare supply reliability, demand, costs and environmental effects','Use rainfall alone to guarantee success','Assume the teaching store is measured Thirlmere data'],0,'Use contextual evidence and distinguish examples from observations.','water-supply')],'glacier-water',['store','dry','shore']),
make('renewable-energy','Renewable energy in upland landscapes',['1.13b: renewable energy','Integrated skill 16: diagram introduction'],[
 ['Water can transfer energy','Hydroelectricity uses water moving through a height difference to drive a turbine linked to a generator. Upland relief and available flow can make suitable sites possible. A run-of-river scheme diverts some flow and returns it downstream; it does not require a vast new reservoir. Low flow, environmental flow requirements, maintenance and design limit output.'],
 ['Benefits have conditions','Renewable generation can reduce reliance on fossil fuels during operation and provide local energy or income. Hydro intakes, pipes, tracks and altered flow can affect habitats and appearance. Construction and maintenance have costs. The National Trust documents a hydro scheme on Stickle Ghyll in Langdale: it is an example elsewhere in the Lake District, not evidence of a hydro plant at Thirlmere.'],
 ['Compare wind and water','Exposed uplands can also be windy. Wind turbines turn moving air into electrical energy, but output varies with wind and operating limits. Turbines, access tracks and power connections can affect views, soils and wildlife; communities may disagree about benefits and costs. Judge a suitable proposal using flow or wind evidence, ecology, landscape, grid access and community needs, not a rule that every upland site should be developed.']
],[['Predict: a hydro intake receives much less usable flow. Other conditions equal, output may…',['Decrease','Become unlimited','Stop depending on water'],0],['A run-of-river scheme typically…',['Diverts some flow through equipment and returns water downstream','Requires all river water to disappear','Always creates the same huge reservoir'],0],['Which is a possible wind-energy trade-off?',['Renewable output versus landscape, habitat and construction effects','Guaranteed constant output with no infrastructure','No need to consider local people'],0],['The named Stickle Ghyll scheme supports which statement?',['Hydropower exists in a Lake District upland setting','A hydro plant must therefore exist at Thirlmere','Every UK river has identical output'],0]],
[q('energy','p1','Hydro turbines are driven by…',['Moving water transferring energy through a height difference','Water being permanently destroyed','Only the colour of a mountain'],0,'Flow and available head influence the usable energy transfer.','hydro'),q('energy','p2','Why retain water in the bypassed stream reach?',['Habitats and other water needs require flow','All rivers should be emptied','A generator needs no environmental context'],0,'Generation must be assessed alongside the river’s ecological and other needs.','energy-impact'),q('energy','p3','Wind-energy generation can vary because…',['Wind and turbine operating conditions vary','Wind speed never changes','All exposed hills have identical output'],0,'Renewable does not mean constant or impact-free.','wind')],
[q('energy','c1','Which combination is important when assessing hydro potential?',['Usable flow and height difference','Only mountain colour','Only a town’s spelling'],0,'Consider water availability and relief alongside scheme constraints.','hydro'),q('energy','c2','An intake and pipeline may change the landscape through…',['Construction disturbance and changed stream flow','A guarantee of no ecological effects','Eliminating all sediment forever'],0,'Engineering benefits and local effects need to be evaluated together.','energy-impact'),q('energy','c3','A renewable-energy proposal should be judged using…',['Resource evidence, ecology, costs, access and community effects','The assumption renewable means no disadvantages','A single decorative diagram without context'],0,'Use site-specific evidence to compare benefits and costs.','energy-judgement'),q('energy','c4','Stickle Ghyll is used here as…',['A documented Langdale hydro example, not a Thirlmere installation','Proof all reservoirs contain generators','A hypothetical name for every wind farm'],0,'Keep named-case evidence geographically precise.','named-energy')],'glacier-energy',['hydro','lowflow','wind']),
make('tourism','Recreation, tourism and path erosion',['1.13b: recreation and tourism','Integrated skill 16: diagram introduction'],[
 ['A landscape attracts people','Glacial valleys, lakes and ridges provide places to walk, climb and enjoy scenery. Visitors can support accommodation, shops, guiding and other jobs; recreation can improve wellbeing. Demand may be seasonal and income is not distributed equally. Traffic, parking, disturbance and pressure on services can create costs for residents and habitats.'],
 ['Boots, bare ground and runoff','Repeated trampling can remove vegetation and compact thin upland soils. Water may then flow along a worn path, carrying loosened sediment and cutting gullies. Walkers avoiding rough or wet sections can widen the damaged area. Rain, slope and soil interact with visitor pressure; visitor numbers alone do not establish an erosion rate.'],
 ['Manage access, not just symptoms','Fix the Fells repairs and maintains Lake District paths. Surfacing, drainage, edge restoration and revegetation can concentrate use on a more durable route and reduce erosion. Such work costs money, needs maintenance and changes a path’s appearance; poorly planned drainage can transfer water or damage elsewhere. Combine access, visitor information and transport management with habitat protection rather than treating closure as the only option.']
],[['Predict: trampling removes vegetation on a steep wet route. Soil may become…',['More exposed to runoff erosion','Guaranteed permanently stable','A new resistant volcanic rock'],0],['Why can walkers avoiding an eroded path worsen damage?',['They can trample and widen its edges','They always restore vegetation instantly','They remove the effect of rain'],0],['A suitable repair can reduce erosion by…',['Managing water and keeping use on a durable route','Guaranteeing no maintenance ever','Making every storm disappear'],0],['A balanced tourism judgement includes…',['Local income and access alongside environmental and resident costs','Only visitor benefits','Only a claim that every visitor causes equal harm'],0]],
[q('tourism','p1','Which is a possible benefit of tourism?',['Income for local services and employment','Guaranteed equal year-round income for everyone','No pressure on transport'],0,'Tourism supports livelihoods, but outcomes vary.','tourism-benefit'),q('tourism','p2','Why can a worn path become a runoff route?',['Compaction and loss of vegetation can favour rapid surface flow','All soil becomes impermeable granite','Rain stops at the path boundary'],0,'Connect trampling, infiltration, flow and sediment removal.','path-erosion'),q('tourism','p3','Why monitor a repaired path?',['Drainage, surfacing and restored edges need maintenance and assessment','Repair guarantees permanent success','Weather cannot affect it again'],0,'Management needs evidence of performance over time.','access-management')],
[q('tourism','c1','Which combines a tourism benefit and cost?',['Local income and increased traffic pressure','Only permanent damage without benefits','Only equal gains without costs'],0,'Evaluation includes different stakeholders and effects.','tourism-benefit'),q('tourism','c2','A plausible path-erosion sequence is…',['Vegetation loss → runoff concentration → sediment removal','Rainfall stops → all rock melts','A path name changes → gravity stops'],0,'Identify the connected physical mechanisms.','path-erosion'),q('tourism','c3','Fix the Fells is an example of…',['Lake District path repair and maintenance','A new glacier forming at Thirlmere','A guarantee all paths are now erosion-free'],0,'The organisation documents practical management, not complete elimination of erosion.','access-management'),q('tourism','c4','Which evidence best tests whether repair works?',['Comparable monitored path condition and runoff/sediment evidence over time','Only an idealised animation','An assumption all paths erode at one rate'],0,'A repeatable monitored comparison is stronger than appearance alone.','management-evidence')],'glacier-tourism',['access','erosion','repair']),
make('conservation','Conserving an upland landscape',['1.13b: conservation','Integrated skill 16: diagram introduction'],[
 ['Conservation involves choices','Conservation aims to protect or restore valued habitats, landforms and landscape character. It can support biodiversity, carbon stores, water quality and recreation. Restricting damaging activity, restoring vegetation or changing grazing may affect livelihoods, access and costs. Objectives and local conditions matter: conservation is not simply leaving every damaged site unchanged.'],
 ['A peatland example','Drainage and loss of protective vegetation can dry peat and expose it to erosion. Blocking suitable drains, stabilising bare surfaces and re-establishing peatland plants can raise water levels and reduce further damage. Cumbria Wildlife Trust documents peat and path restoration at Armboth Fell. This is a named regional example; the model does not claim the whole Thirlmere catchment is peat or that every restoration eliminates floods.'],
 ['Judge results over time','Restoration requires design, funding, permissions, land-manager cooperation and maintenance. Monitor vegetation, water levels, erosion and habitat condition against appropriate baselines and comparison sites. Benefits can take time and a wet peatland can still generate runoff. Evaluate carbon, ecology and water outcomes alongside farming, visitor access and other needs; avoid a universal best intervention for every slope.']
],[['Predict: a suitable damaged peat drain is blocked. Local water levels may…',['Rise and help rewet peat','Always fall to zero','Prove that no further runoff can occur'],0],['Why restore vegetation on bare peat?',['It can protect the surface and support habitat recovery','It turns all peat into concrete','It removes every management cost'],0],['Which is a possible conservation trade-off?',['Habitat recovery alongside changed grazing, access and costs','Unlimited benefit without affected users','A guarantee no maintenance is needed'],0],['What tests a restoration claim?',['Monitored vegetation, water and erosion evidence with context','Only a drawing of a green slope','The assumption every site responds identically'],0]],
[q('conserve','p1','Which action can help rewet suitable drained peat?',['Blocking selected drainage channels','Deepening every drain without assessment','Removing all vegetation'],0,'Drain blocking can raise local water levels; design and context matter.','peat-restoration'),q('conserve','p2','Why does conservation involve people as well as habitats?',['Land use, access, livelihoods and funding can be affected','No one uses upland landscapes','All users have identical objectives'],0,'Different interests need negotiation and evidence.','conservation-tradeoff'),q('conserve','p3','A restored peatland can still generate runoff because…',['Storage and flow pathways are finite and conditions vary','Restoration permanently removes all water','A wet habitat never receives rain'],0,'Do not turn potential hydrological benefits into a flood-prevention guarantee.','restoration-limits')],
[q('conserve','c1','A purpose of stabilising and revegetating bare peat is to…',['Reduce erosion and aid habitat recovery','Guarantee no water ever leaves the slope','Create a hydro turbine automatically'],0,'Vegetation and surface treatment can protect damaged peat.','peat-restoration'),q('conserve','c2','Which is a defensible conservation judgement?',['Compare ecological benefits with costs and effects on land users','Assume conservation never changes livelihoods','Choose the same measure for every habitat'],0,'Evaluate place-specific objectives and trade-offs.','conservation-tradeoff'),q('conserve','c3','Armboth Fell is cited as…',['A documented Cumbria peat and path restoration example','Proof every Thirlmere slope is deep peat','A fabricated name for every restored bog'],0,'Keep named evidence limited to what the source supports.','named-conservation'),q('conserve','c4','Strong evaluation of restoration needs…',['Baseline and follow-up monitoring with relevant comparisons','Only the green colour of an animation','A claim that benefits are instantaneous everywhere'],0,'Evidence over time tests outcomes and limitations.','management-evidence')],'glacier-conservation',['intact','restore','monitor']),
make('thirlmere-helvellyn','Thirlmere and Helvellyn: a landscape study',['1.14a'],[
 ['Locate and explain the bedrock','Thirlmere and Helvellyn lie in the central Lake District, Cumbria, northwest England. The Thirlmere valley runs beside Helvellyn’s upland massif. The area is largely underlain by Borrowdale Volcanic Group rocks, including ancient lavas and tuffs. Volcanic origins help explain resistant craggy terrain; today’s mountains are not the original volcanic cones. The locator shows selected relationships, not mapped geological boundaries.'],
 ['Ice reshaped an older landscape','Glaciers enlarged and deepened valleys in the Lake District, leaving troughs and basins among the fells. The Thirlmere setting combines this glacial inheritance with subsequent streams, weathering and slope activity. Jorge Franganillo’s2012 photograph shows water, steep valley sides and woodland; it cannot independently reveal rock type, formation age or the full sequence. Use geological and historical sources alongside it.'],
 ['People altered the inherited valley','The national park’s account describes the enlargement of two smaller waters by a dam and an aqueduct connected to Manchester in1894. This changed the water body, shoreline and earlier land uses; woodland management and recreation add later influences. Distinguish scales: geology and ice explain the wider relief, while reservoir engineering strongly explains the modern water level and shore. Farming, forestry, weather, access and conservation continue to matter. Their relative importance depends on the feature and time period being explained.']
],[['Predict: compare the whole upland relief with a modern reservoir shoreline. The most relevant explanations may…',['Differ by feature and time period','Always be one identical factor','Exclude all human action'],0],['Which statement about volcanic geology is supported?',['Ancient volcanic rocks underlie much of this craggy area','Helvellyn is an unchanged original volcanic cone','Every Lake District rock is the same lava'],0],['The nineteenth-century dam mainly changed…',['Water levels, shores and inundated land within the valley','The original age of the volcanic rocks','Past glacial climate everywhere'],0],['What can one dated landscape photograph establish?',['Visible features at that moment, not a complete formation history','The exact rate of glacial erosion','The rock type of every slope without other evidence'],0]],
[q('case','p1','This named landscape is located in…',['The central Lake District in northwest England','The South Downs in southeast England','The Sahara Desert'],0,'Locate the named place before explaining its landforms.','thirlmere-location'),q('case','p2','Which pairing connects feature and factor?',['Glacial valley relief with ice erosion; modern shore with reservoir engineering','Ancient rock age with the1894 aqueduct alone','Every tree with a present glacier'],0,'Select explanations at the right spatial and temporal scale.','landscape-synthesis'),q('case','p3','Why combine photograph, geology and history?',['Each supports different parts of the explanation','A single photo proves every process and date','Sources never differ in what they can establish'],0,'Use complementary evidence and respect its limits.','case-evidence')],
[q('case','c1','The named landscape’s volcanic rocks belong largely to the…',['Borrowdale Volcanic Group','Modern concrete poured in1894','Only loose marine beach sand'],0,'The geological context is verified separately from the photograph.','thirlmere-geology'),q('case','c2','Which major human development changed the modern water body?',['Reservoir enlargement and water-supply infrastructure','A present-day glacier filling the entire valley','Only the formation of lava millions of years ago'],0,'Engineering changes must be distinguished from ancient relief formation.','thirlmere-change'),q('case','c3','What is clearly visible in the supplied photograph?',['Water bordered by wooded and steep valley sides','A turbine’s measured annual generation','A dated sequence of glacier retreat'],0,'The image supports visible landscape description, not hidden history or performance.','photo-evidence'),q('case','c4','Which best evaluates the most significant factors?',['Judge geology, glaciation and human alteration for the feature and period concerned','Use the same single factor for every feature','Treat the schematic locator as a detailed OS survey'],0,'A named study needs evidence-led comparison, not a universal ranking.','landscape-synthesis')],'glacier-thirlmere',['locate','photo','engineering'])
];
